def is_happy(s):
    """Check if a string is happy.

    A string is happy if its length is at least 3
    and every 3 consecutive letters are distinct.
    """
    if len(s) < 3:
        return False
    for i in range(2, len(s)):
        # Check that s[i-2], s[i-1], s[i] are all distinct
        if len({s[i - 2], s[i - 1], s[i]}) != 3:
            return False
    return True

