def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}
    """
    if not test.strip():
        return {}

    # Count occurrences of each letter
    counts = {}
    for letter in test.split():
        counts[letter] = counts.get(letter, 0) + 1

    # Find the maximum count
    max_count = max(counts.values())

    # Return all letters with the maximum count
    return {letter: count for letter, count in counts.items() if count == max_count}

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3
    '''
    # Case 1: Contains whitespace — split on whitespace
    if ' ' in txt:
        return txt.split()

    # Case 2: No whitespace but contains commas — split on commas
    if ',' in txt:
        return txt.split(',')

    # Case 3: No whitespace and no commas — count lowercase letters
    # with odd ordinal position in the alphabet (b=1, d=3, f=5, ...)
    return sum(
        1 for ch in txt
        if 'a' <= ch <= 'z' and (ord(ch) - ord('a')) % 2 == 1
    )

def minPath(grid, k):
    N = len(grid)

    # Step 1: Find the position of the minimum value (starting cell)
    min_val = float('inf')
    min_pos = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] < min_val:
                min_val = grid[i][j]
                min_pos = (i, j)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    result = []
    current_pos = min_pos

    for _ in range(k):
        ci, cj = current_pos
        result.append(grid[ci][cj])

        # Find the smallest-valued neighbor for the next step
        best_val = float('inf')
        best_pos = None
        for di, dj in directions:
            ni, nj = ci + di, cj + dj
            if 0 <= ni < N and 0 <= nj < N:
                if grid[ni][nj] < best_val:
                    best_val = grid[ni][nj]
                    best_pos = (ni, nj)

        if best_pos is not None:
            current_pos = best_pos

    return result

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """

    def to_float(val):
        """Convert any supported input type to a float for comparison."""
        if isinstance(val, str):
            # Replace comma decimal separator with period
            cleaned = val.replace(",", ".")
            return float(cleaned)
        else:
            return float(val)

    num_a = to_float(a)
    num_b = to_float(b)

    if abs(num_a - num_b) < 1e-9:
        return None
    elif num_a > num_b:
        return a
    else:
        return b

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    def is_prime(num):
        if num < 2:
            return False
        if num < 4:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    return x if is_prime(n) else y

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even = 0
    odd = 0
    for digit in str(abs(num)):
        d = int(digit)
        if d % 2 == 0:
            even += 1
        else:
            odd += 1
    return (even, odd)

import hashlib
def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
